import { $, $$, isoToday, state, persist, toast, roleName, user, userAvatar, svg, esc, fmtDate, sessionMedia } from './core.js';
import { render, go, view, auth, avatarAssets, renderCommunityFeed } from './views.js';
import { openModal, closeModal, pressButton, releaseButton } from './motion.js';

function dismissModal(){const root=$('#modal-root');if(root.querySelector('.compose-sheet')&&selectedMedia?.url){URL.revokeObjectURL(selectedMedia.url);selectedMedia=null;}if(root.querySelector('.compose-sheet')&&selectedStory?.url){URL.revokeObjectURL(selectedStory.url);selectedStory=null;}closeModal(root,()=>{root.innerHTML='';});}
function modal(title,body,actions='',variant=''){const root=$('#modal-root');root.innerHTML=`<section class="modal ${variant}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="modal-head"><h2>${esc(title)}</h2><button class="modal-close" data-action="close-modal" aria-label="Close">×</button></header>${body}${actions?`<footer class="modal-actions">${actions}</footer>`:''}</section>`;root.onclick=event=>{if(event.target===root)dismissModal();};openModal(root,variant);root.querySelector('input:not([type=hidden]),textarea,select,button')?.focus({preventScroll:true});}
function commentMarkup(post){
  const comments=post.comments.map((comment,index)=>({...comment,id:comment.id||`${post.id}-comment-${index}`}));
  const renderNode=(comment,depth=0)=>`<article class="thread-comment" style="--reply-depth:${Math.min(depth,3)}"><div class="thread-comment-copy"><strong>${esc(comment.author)}</strong><p>${esc(comment.text)}</p><button type="button" class="reply-link" data-action="reply-to" data-post-id="${esc(post.id)}" data-comment-id="${esc(comment.id)}" data-author="${esc(comment.author)}">Reply</button></div>${comments.filter(child=>child.parentId===comment.id).map(child=>renderNode(child,depth+1)).join('')}</article>`;
  const roots=comments.filter(comment=>!comment.parentId||!comments.some(item=>item.id===comment.parentId));
  return `${roots.map(comment=>renderNode(comment)).join('')||'<p class="empty-thread">Be the first to respond thoughtfully.</p>'}<div class="reply-target" id="reply-target" hidden><span></span><button type="button" data-action="cancel-reply" aria-label="Cancel reply">×</button></div><form class="comment-form" data-post-id="${esc(post.id)}"><input type="hidden" name="parentId" value="" /><label class="sr-only" for="reply-content">Your reply</label><textarea id="reply-content" name="comment" rows="2" maxlength="600" placeholder="Add a thoughtful reply…" required></textarea><button class="btn primary" type="submit">Reply</button></form>`;
}
function openComments(post){
  if(!post)return;
  modal('Discussion',`<div class="discussion-context"><div class="post-community">in ${esc(post.community)} · ${esc(post.time)}</div><h3>${esc(post.title)}</h3><p>${esc(post.body)}</p></div><div class="thread-list" aria-label="Replies">${commentMarkup(post)}</div>`, '', 'comments-sheet');
}
function logSymptom(){modal('Log a symptom',`<p class="modal-intro">Capture what you noticed. A small note is enough. This is saved only in the browser demo. Do not enter real health information.</p><form id="symptom-form"><div class="form-field"><label for="symptom-name">What did you notice?</label><input id="symptom-name" name="symptom" required placeholder="e.g. Headache, fatigue" /></div><div class="form-field"><label for="symptom-severity">How intense was it?</label><select id="symptom-severity" name="severity"><option>Mild</option><option selected>Moderate</option><option>Severe</option></select></div><div class="form-field"><label for="symptom-duration">How long did it last?</label><input id="symptom-duration" name="duration" placeholder="Optional" /></div><div class="form-field"><label for="symptom-note">Anything else you noticed?</label><textarea id="symptom-note" name="note" placeholder="Timing, context or anything you’d like to remember"></textarea></div><div class="form-field"><label for="symptom-date">Date</label><input type="date" id="symptom-date" name="date" value="${isoToday}" /></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Save on this device</button></div></form>`)}
let selectedMedia=null;
let selectedStory=null;
let avatarDraft=null;
let avatarTarget='signup';
function loadAvatarFile(file){if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>3*1024*1024){toast('Choose a JPG, PNG or WebP image under 3 MB');return;}const reader=new FileReader();reader.onload=()=>{avatarDraft={src:String(reader.result),kind:'custom',crop:{x:50,y:50,zoom:1}};$$('[data-avatar-option]').forEach(option=>option.classList.remove('selected'));updateAvatarTray();};reader.onerror=()=>toast('This image could not be opened. Choose another file.');reader.readAsDataURL(file);}
function avatarPreviewMarkup(){const source=avatarDraft?.src||'';const crop=avatarDraft?.crop||{x:50,y:50,zoom:1};return source?`<img class="avatar-crop-image" src="${esc(source)}" alt="Selected profile picture preview" style="object-position:${crop.x}% ${crop.y}%;transform:scale(${crop.zoom})" />`:`<span class="avatar-fallback">VC</span>`;}
function updateAvatarTray(){const preview=$('#avatar-live-preview');if(preview)preview.innerHTML=avatarPreviewMarkup();const name=avatarTarget==='signup'?(auth.draft.displayName||auth.draft.name||'Your name'):(user().displayName||user().name||'Your name');const handle=avatarTarget==='signup'?(auth.draft.handle||'yourname'):(user().handle||'yourname');const bio=avatarTarget==='signup'?(auth.draft.bio||'Your story, at your pace.'):(user().bio||'Your story, at your pace.');const profile=$('#avatar-profile-preview');if(profile)profile.innerHTML=`${avatarPreviewMarkup()}<strong>${esc(name)}</strong><small>@${esc(handle)}</small><p>${esc(bio)}</p>`;const x=$('#avatar-x'),y=$('#avatar-y'),zoom=$('#avatar-zoom');if(x)x.value=String(avatarDraft?.crop.x??50);if(y)y.value=String(avatarDraft?.crop.y??50);if(zoom)zoom.value=String(avatarDraft?.crop.zoom??1);}
function openAvatarPicker(target){avatarTarget=target;const source=target==='signup'?auth.draft.avatar:user().avatar;const crop=target==='signup'?auth.draft.avatarCrop:user().avatarCrop;const fallback=avatarAssets.find(asset=>asset.path.endsWith('/Jaime.jpg'))||avatarAssets[0];avatarDraft={src:source||fallback?.url||'',kind:'preset',crop:{x:Number(crop?.x??50),y:Number(crop?.y??50),zoom:Number(crop?.zoom??1)}};const grid=avatarAssets.map((asset,index)=>`<button type="button" class="avatar-tray-choice ${avatarDraft.src===asset.url?'selected':''}" data-avatar-option="${esc(asset.url)}" aria-label="Choose profile picture ${index+1}"><img src="${esc(asset.url)}" alt=""/><i>${svg('check',13)}</i></button>`).join('');modal('Make it yours.',`<p class="avatar-tray-subtitle">Choose an image that represents you.</p><div class="avatar-tray-layout"><section class="avatar-tray-gallery"><div class="avatar-tray-section-title">From Vericove <span>${avatarAssets.length} portraits</span></div><div class="avatar-tray-grid">${grid||'<p class="empty-avatar">No profile pictures were found.</p>'}</div><section class="avatar-upload-card" id="avatar-dropzone"><div class="upload-symbol">${svg('upload',17)}</div><div><strong>Bring your own picture</strong><small>Drag an image here, or browse your device · JPG, PNG or WebP · up to 3 MB</small></div><label class="btn small">Browse<input id="avatar-tray-file" type="file" accept="image/png,image/jpeg,image/webp" hidden></label></section><div class="avatar-crop-controls"><div><label for="avatar-x">Horizontal</label><input id="avatar-x" type="range" min="0" max="100" value="50"/></div><div><label for="avatar-y">Vertical</label><input id="avatar-y" type="range" min="0" max="100" value="50"/></div><div><label for="avatar-zoom">Zoom</label><input id="avatar-zoom" type="range" min="1" max="2.5" value="1" step="0.01"/></div></div><p class="avatar-crop-hint">Adjust the crop and zoom, then confirm. Your current profile picture stays in place until you confirm.</p></section><aside class="avatar-tray-preview"><div class="avatar-live-ring" id="avatar-live-preview">${avatarPreviewMarkup()}</div><span class="avatar-edit-dot">${svg('upload',12)}</span><small>LIVE PREVIEW</small><div class="avatar-mini-profile" id="avatar-profile-preview"></div><button class="text-link avatar-reset" data-action="avatar-reset">Reset to default</button></aside></div>`,`<button type="button" class="btn ghost" data-action="avatar-cancel">Cancel</button><button type="button" class="btn primary" data-action="avatar-confirm">Use this picture</button>`,'avatar-tray');updateAvatarTray();}
function storyComposer(){selectedStory=null;modal('Add to your story',`<p class="modal-intro">Share a photo or short video with your circles. Stories stay in this browser preview.</p><form id="story-form"><div class="form-field"><label for="story-caption">Caption</label><input id="story-caption" name="caption" maxlength="100" placeholder="A small moment to share…" /></div><div class="attachment-row"><input id="story-media" type="file" accept="image/*,video/*" hidden /><button class="attachment-button" type="button" data-action="attach-story">${svg('upload',14)}Choose photo or video</button><small>Up to 20 MB · preview only</small></div><div class="attachment-preview" id="story-preview" hidden></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Share story</button></div></form>`, '', 'compose-sheet')}
function viewStory(id){const story=(state.stories||[]).find(item=>item.id===id),media=sessionMedia.get(`story:${id}`);if(!story)return;const mediaMarkup=media?(media.type==='video'?`<video class="story-view-media" src="${media.url}" controls autoplay playsinline></video>`:`<img class="story-view-media" src="${media.url}" alt="${esc(story.author)}’s story" />`):'';modal(story.author,`<div class="story-viewer">${mediaMarkup}<p>${esc(story.caption||'A moment shared with the community.')}</p></div>`, '', 'story-sheet')}

function composePost(kind='Question'){
  const videoMode=kind==='Video';
  if(selectedMedia?.url)URL.revokeObjectURL(selectedMedia.url);
  selectedMedia=null;
  modal(videoMode?'Share a video':'Start a discussion',`<p class="modal-intro">${videoMode?'Add a short video to your community feed.':'Share an experience or ask a question.'} Your pseudonym is selected by default.</p><form id="post-form" data-video-mode="${videoMode}"><div class="form-field"><label for="post-type">What would you like to share?</label><select name="tag" id="post-type">${(videoMode?['Video']:['Question','Experience','Treatment experience','Doctor experience','General discussion']).map(option=>`<option ${kind.toLowerCase()===option.toLowerCase()?'selected':''}>${option}</option>`).join('')}</select></div><div class="form-field"><label for="post-community">Choose a circle</label><select name="community" id="post-community">${['Endometriosis support','Living with chronic pain','Women’s health questions','Menstrual health'].map(item=>`<option>${item}</option>`).join('')}</select></div><div class="form-field"><label for="post-title">Title</label><input id="post-title" name="title" maxlength="150" required placeholder="What would you like people to know?" /></div><div class="form-field"><label for="post-body">Your story or question</label><textarea id="post-body" name="body" required maxlength="1200" placeholder="Share what happened for you. Avoid identifying details."></textarea><small class="form-hint">Personal experiences are not medical advice. Leave out names, addresses and private records.</small></div><div class="attachment-row"><input id="post-photo" type="file" accept="${videoMode?'video/*':'image/*,video/*'}" hidden /><button class="attachment-button" type="button" data-action="attach-photo">${svg(videoMode?'upload':'file',14)}${videoMode?'Choose a video':'Add a photo or video'}</button><small>Temporary preview on this device</small></div><div class="attachment-preview" id="media-preview" hidden><img id="media-preview-image" alt="Selected photo preview" /><button type="button" data-action="remove-photo">Remove photo</button></div><div class="form-check"><input id="post-anonymous" type="checkbox" name="anonymous" value="yes" checked /><label for="post-anonymous">Post under my community pseudonym: <b>${esc(user().handle||'Member')}</b></label></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button type="submit" class="btn primary">Share with the community</button></div></form>`, '', 'compose-sheet');
}
function followCommunity(name){if(state.followed.includes(name))state.followed=state.followed.filter(item=>item!==name);else state.followed.push(name);persist();render();toast(state.followed.includes(name)?`Following ${name}`:`Unfollowed ${name}`)}

function onAction(button){const action=button.dataset.action,id=button.dataset.id,post=state.posts.find(item=>item.id===id);switch(action){
  case 'log-symptom':logSymptom();break;
  case 'compose':composePost(button.dataset.kind||'Question');break;
  case 'compose-video':composePost('Video');break;
  case 'add-story':storyComposer();break;
  case 'view-story':viewStory(id);break;
  case 'remove-story-media':if(selectedStory?.url)URL.revokeObjectURL(selectedStory.url);selectedStory=null;$('#story-preview').innerHTML='';$('#story-preview').hidden=true;break;
  case 'story-prompt':toast(`${button.dataset.name}'s story is an example. Share your own story with the button above.`);break;
  case 'attach-photo':$('#post-photo')?.click();break;
  case 'attach-story':$('#story-media')?.click();break;
  case 'remove-photo':if(selectedMedia?.url)URL.revokeObjectURL(selectedMedia.url);selectedMedia=null;$('#media-preview').innerHTML='';$('#media-preview').hidden=true;$('#post-photo').value='';break;
  case 'close-modal':dismissModal();break;
  case 'vote':if(post){const previous=post.vote||(post.voted?1:0),next=Number(button.dataset.vote);post.vote=previous===next?0:next;post.voted=post.vote===1;post.votes+=post.vote-previous;persist();render()}break;
  case 'save-post':if(post){post.saved=!post.saved;persist();render();toast(post.saved?'Saved to your discussions':'Removed from saved discussions')}break;
  case 'toggle-comments':openComments(post);break;
  case 'reply-to':{const form=$('.comment-form'),target=$('#reply-target'),input=$('#reply-content');if(form&&target&&input){form.querySelector('[name="parentId"]').value=button.dataset.commentId;target.querySelector('span').textContent=`Replying to ${button.dataset.author}`;target.hidden=false;input.placeholder=`Reply to ${button.dataset.author}…`;input.focus();}}break;
  case 'cancel-reply':{const form=$('.comment-form'),target=$('#reply-target'),input=$('#reply-content');if(form&&target&&input){form.querySelector('[name="parentId"]').value='';target.hidden=true;input.placeholder='Add a thoughtful reply…';input.focus();}}break;
  case 'share-post':modal('Share this discussion',`<p class="modal-intro">Copy a link to this example discussion on the current device.</p><div class="form-field"><label for="share-url">Discussion link</label><input id="share-url" readonly value="${esc(location.href.split('#')[0]+'#'+id)}" /></div><div class="modal-actions"><button class="btn" data-action="close-modal">Close</button><button class="btn primary" data-action="copy-post-link" data-id="${esc(id)}">Copy link</button></div>`);break;
  case 'copy-post-link':navigator.clipboard?.writeText(location.href.split('#')[0]+'#'+id).then(()=>toast('Link copied')).catch(()=>toast('Select and copy the link above'));break;
  case 'follow':followCommunity(button.dataset.community);break;
  case 'browse-communities':modal('Explore communities',`<p class="modal-intro">Find spaces for shared experience. Joining does not share your personal health records.</p><div class="community-list">${communityItems()}</div>`);break;
  case 'guidelines':modal('Community guidelines',`<ol class="guideline-list"><li>Speak from your own experience; avoid presenting it as universal medical advice.</li><li>Protect privacy. Do not post identifying details or someone else’s health information.</li><li>Respect different journeys and care decisions.</li><li>Keep discussions supportive. Report harmful or misleading content.</li><li>Verified professionals should be clear about their role and stay within appropriate boundaries.</li></ol><div class="research-sidebar-box"><strong>Community conversations are peer support</strong>They do not replace advice from a qualified healthcare professional.</div>`);break;
  case 'report-post':modal('Report this discussion',`<p class="modal-intro">Save a report to the local moderation preview. It will not be sent to a service.</p><form id="report-form" data-post="${esc(id)}"><div class="form-field"><label for="report-reason">Reason</label><select id="report-reason" name="reason"><option>Personal information</option><option>Potentially harmful medical advice</option><option>Harassment</option><option>Spam</option><option>Other concern</option></select></div><div class="form-field"><label for="report-details">More details (optional)</label><textarea name="details" id="report-details"></textarea></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Save report</button></div></form>`);break;
  case 'own-post-menu':if(post)modal('Your discussion',`<p class="modal-intro">You can edit or remove this post from your local community preview.</p><div class="modal-actions"><button class="btn" data-action="edit-post" data-id="${esc(id)}">Edit post</button><button class="btn" data-action="close-modal">Keep post</button><button class="btn danger" data-action="delete-post" data-id="${esc(id)}">Delete</button></div>`);break;
  case 'edit-post':if(post)modal('Edit your post',`<form id="edit-post-form" data-id="${esc(id)}"><div class="form-field"><label>Title</label><input name="title" maxlength="150" required value="${esc(post.title)}" /></div><div class="form-field"><label>Post</label><textarea name="body" maxlength="1200" required>${esc(post.body)}</textarea></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary">Save changes</button></div></form>`);break;
  case 'delete-post':state.posts=state.posts.filter(item=>item.id!==id);persist();dismissModal();render();toast('Your post was removed from this browser preview');break;
  case 'write-review':modal('Preview a care review',`<p class="modal-intro">This local flow previews structured feedback. No real provider is listed, and nothing is published or transmitted.</p><form id="review-form"><div class="form-field"><label>Directory example</label><select name="provider"><option>Illustrative provider listing</option></select></div>${['Listened carefully','Took my concerns seriously','Explained their reasoning','I felt respected'].map((label,i)=>`<div class="form-field"><label>${label}</label><select name="rating${i}"><option>Yes</option><option>Somewhat</option><option>No</option><option>Prefer not to say</option></select></div>`).join('')}<div class="form-field"><label for="review-note">Brief experience (optional)</label><textarea name="note" id="review-note" maxlength="600" placeholder="Please leave out personal details"></textarea></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Save local preview</button></div></form>`);break;
  case 'doctor-profile':modal(button.dataset.name,`<p class="modal-intro">Specialty listing preview · No provider record is connected.</p><div class="research-sidebar-box"><strong>Not a real clinician profile</strong>Credentials, location, availability and patient ratings are not available in this prototype. A production directory should show each verified claim separately.</div>`, '', 'profile-sheet');break;
  case 'save-provider':state.savedProviders.includes(button.dataset.name)?state.savedProviders=state.savedProviders.filter(n=>n!==button.dataset.name):state.savedProviders.push(button.dataset.name);persist();dismissModal();toast('Provider list updated');break;
  case 'share-consent':modal('Research matching privacy choice',`<p class="modal-intro">This demo does not include journal details in research enquiries. The toggle below records a local preference only.</p><div class="form-check"><input type="checkbox" id="match-consent" ${state.consent.researchMatching?'checked':''} /><label for="match-consent">Allow a reviewed health summary to be used when preparing a research enquiry. This does not send anything automatically.</label></div><div class="research-sidebar-box"><strong>You can change this choice later</strong>Every enquiry remains a draft until you review it and approve sharing.</div><div class="modal-actions"><button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-consent">Save choice</button></div>`);break;
  case 'save-consent':state.consent.researchMatching=$('#match-consent')?.checked||false;persist();dismissModal();toast('Your sharing choice is saved');break;
  case 'draft-enquiry':modal(`Draft a research enquiry`, `<p class="modal-intro">This local draft is not addressed to a real person or sent anywhere.</p><form id="enquiry-form"><div class="form-field"><label for="enquiry-text">Enquiry draft</label><textarea id="enquiry-text" name="message" required>Describe the research topic you would like to ask about. Leave out your identity and private health details.</textarea></div><div class="form-check"><input type="checkbox" required id="enquiry-approve" /><label for="enquiry-approve">I reviewed this draft for personal and health information.</label></div><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Keep as draft</button><button class="btn primary" type="submit">Save draft here</button></div></form>`);break;
  case 'paper-details':{const paper=researchPapers.find(p=>p.id===id);if(paper)modal('Research details',`<div class="paper-type">${esc(paper.type)} · ${esc(paper.status)}</div><h3 class="post-title">${esc(paper.title)}</h3><p class="entry-meta">${esc(paper.authors)}<br>${esc(paper.journal)}</p><p class="entry-note">${esc(paper.summary)}</p><div class="research-sidebar-box"><strong>Limitations</strong>${esc(paper.limitations)}</div><div class="paper-foot"><span class="source-tag">Source: ${esc(paper.source)}</span><button class="btn small" data-action="save-paper" data-id="${esc(paper.id)}">Save to collection</button></div>`, '', 'reading-view');break;}
  case 'save-paper':if(state.savedPapers.includes(id))state.savedPapers=state.savedPapers.filter(paperId=>paperId!==id);else state.savedPapers.push(id);persist();render();toast(state.savedPapers.includes(id)?'Added to your research collection':'Removed from your research collection');break;
  case 'research-sort':toast('Research feed sorted by relevance');break;
  case 'upload-record':$('#record-file')?.click();break;
  case 'view-record':modal(button.dataset.name,`<p class="modal-intro">This is sample record metadata in a local demo. A deployed system should encrypt files and restrict access.</p><div class="research-sidebar-box"><strong>Sample record</strong>This sample record name is stored in browser local storage, which is not an access-controlled health-record system.</div>`);break;
  case 'add-medication':modal('Add a treatment note',`<p class="modal-intro">Sample details are stored only in this browser. Don’t enter real medical information.</p><form id="medication-form"><div class="form-field"><label>Name</label><input name="name" required placeholder="Medication or treatment" /></div><div class="form-field"><label>Notes</label><textarea name="notes" placeholder="Optional note for your own reference"></textarea></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Save on this device</button></div></form>`);break;
  case 'remove-medication':state.medications=state.medications.filter(item=>String(item.id)!==String(id));persist();render();toast('Treatment note removed from this device');break;
  case 'generate-report':go('reports');toast('Review your draft and choose what to include');break;
  case 'share-report':if(!$('#report-consent')?.checked){toast('Review and confirm before previewing the report');break;}modal('Private summary preview',`<p class="modal-intro">This preview shows the type of summary the app can prepare. It has not been shared with anyone.</p><div class="research-sidebar-box"><strong>Sharing is not connected</strong>A production app needs secure, revocable sharing and an explicit recipient step.</div>`);break;
  case 'upload-research':modal('Add research to your profile',`<p class="modal-intro">Create a local draft with a source link. The item is not independently checked or published.</p><form id="upload-research-form"><div class="form-field"><label>Title</label><input name="title" required /></div><div class="form-field"><label>Source link or DOI</label><input name="source" placeholder="https:// or DOI" required /></div><div class="form-field"><label>Evidence status (your label)</label><select name="status"><option>Unreviewed</option><option>Peer-reviewed (self-reported)</option><option>Preprint (self-reported)</option><option>Research summary</option></select></div><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Cancel</button><button class="btn primary">Save on this device</button></div></form>`);break;
  case 'admin-queue':go('verification');break;
  case 'review-application':modal(`Review ${button.dataset.name}`,`<p class="modal-intro">Claims are reviewed independently. Verify evidence against the relevant official registry.</p><div class="community-stat"><span>Identity</span><strong>Pending</strong></div><div class="community-stat"><span>Registration</span><strong>Under review</strong></div><div class="community-stat"><span>Primary qualification</span><strong>Needs evidence</strong></div><div class="modal-actions"><button class="btn" data-action="close-modal">Close</button><button class="btn" data-action="request-evidence">Request evidence</button><button class="btn primary" data-action="approve-claim">Approve verified claims</button></div>`);break;
  case 'request-evidence':case 'approve-claim':dismissModal();toast('Review action recorded in this demo');break;
  case 'moderate':modal('Review report',`<p class="modal-intro">Review this report against the community guidelines. This action is a demo.</p><div class="modal-actions"><button class="btn" data-action="close-modal">Dismiss report</button><button class="btn primary" data-action="hide-post" data-id="${esc(id)}">Hide reported post</button></div>`);break;
  case 'hide-post':state.posts=state.posts.filter(item=>item.id!==id);persist();dismissModal();render();toast('Post hidden from the demo community feed');break;
  case 'mark-read':state.notifications.forEach(n=>n.read=true);persist();render();toast('Notifications marked as read');break;
  case 'account-menu':modal('Your account',`<div class="record-list"><button class="topic" data-action="change-role"><span class="topic-emoji">${svg('user',14)}</span><span><strong>Change workspace role</strong><small>Preview patient, doctor or researcher screens</small></span><span class="topic-arrow">›</span></button><button class="topic" data-route="settings"><span class="topic-emoji">${svg('shield',14)}</span><span><strong>Privacy & settings</strong><small>Sharing choices and account controls</small></span><span class="topic-arrow">›</span></button><button class="topic" data-action="signout"><span class="topic-emoji">↗</span><span><strong>Sign out</strong><small>End this browser session</small></span><span class="topic-arrow">›</span></button></div>`);break;
  case 'change-role':rolePicker();break;
  case 'edit-profile':modal('Edit profile',`<form id="profile-form"><div class="form-field"><label for="profile-display">Display name</label><input id="profile-display" name="displayName" value="${esc(user().displayName||user().name||'')}" required maxlength="50" /></div><div class="form-field"><label for="profile-handle">Username</label><input id="profile-handle" name="handle" value="${esc(user().handle||'')}" required maxlength="24" /></div><div class="form-field"><label for="profile-bio-edit">Bio</label><textarea id="profile-bio-edit" name="bio" maxlength="240" placeholder="Tell the community a little about yourself">${esc(user().bio||'')}</textarea></div><div class="form-field"><label for="profile-interests">Interests</label><input id="profile-interests" name="interests" value="${esc((user().interests||[]).join(', '))}" placeholder="Wellness, nutrition, research…"/><small class="form-hint">Separate interests with commas. Interests don’t imply a health condition.</small></div>${user().role==='doctor'||user().role==='researcher'?`<div class="form-field"><label for="profile-specialty">${user().role==='doctor'?'Specialty':'Institution or research field'}</label><input id="profile-specialty" name="specialty" value="${esc(user().specialty||user().institution||'')}" /></div>`:''}<p class="form-hint">Changes are stored in this browser preview.</p><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary">Save on this device</button></div></form>`);break;
  case 'open-avatar-picker':openAvatarPicker(state.session?.loggedIn?'profile':'signup');break;
  case 'avatar-option':{const src=button.dataset.src;avatarDraft={src,kind:'preset',crop:{x:50,y:50,zoom:1}};$$('[data-avatar-option]').forEach(option=>option.classList.toggle('selected',option.dataset.avatarOption===src));updateAvatarTray();break;}
  case 'avatar-reset':{const fallback=avatarAssets.find(asset=>asset.path.endsWith('/Jaime.jpg'))||avatarAssets[0];avatarDraft={src:fallback?.url||'',kind:'preset',crop:{x:50,y:50,zoom:1}};$$('[data-avatar-option]').forEach(option=>option.classList.toggle('selected',option.dataset.avatarOption===avatarDraft.src));updateAvatarTray();break;}
  case 'avatar-cancel':avatarDraft=null;dismissModal();break;
  case 'avatar-confirm':{if(!avatarDraft?.src){toast('Choose a profile picture first');break;}const selection={avatar:avatarDraft.src,avatarCrop:{...avatarDraft.crop}};if(avatarTarget==='signup'){auth.draft.avatar=selection.avatar;auth.draft.avatarCrop=selection.avatarCrop;const button=$('.avatar-launch-preview');if(button)button.innerHTML=`<img src="${esc(selection.avatar)}" alt="" style="object-position:${selection.avatarCrop.x}% ${selection.avatarCrop.y}%;transform:scale(${selection.avatarCrop.zoom})"/>`;const preview=$('.profile-mini-preview>img');if(preview){preview.src=selection.avatar;preview.style.objectPosition=`${selection.avatarCrop.x}% ${selection.avatarCrop.y}%`;preview.style.transform=`scale(${selection.avatarCrop.zoom})`;}}else{state.session.avatar=selection.avatar;state.session.avatarCrop=selection.avatarCrop;persist();}avatarDraft=null;dismissModal();if(avatarTarget==='profile'){render();toast('Profile picture saved on this device');}break;}
  case 'complete-signup':{if(!$('#privacy-check')?.checked){toast('Please confirm this local prototype profile');break;}const d=auth.draft;state.session={loggedIn:true,remembered:true,demo:true,name:d.name||'Alex Morgan',displayName:d.displayName||d.name||'Alex Morgan',email:d.email||'',role:d.role||'patient',handle:d.handle||'QuietRiver',avatar:d.avatar||'',avatarCrop:d.avatarCrop||{x:50,y:50,zoom:1},banner:d.banner||'warm',bannerImage:d.bannerImage||'',bio:d.bio||'',interests:d.interests||[],specialty:d.specialty||'',institution:d.institution||'',privacy:d.privacy||{},anonymous:d.anonymous!==false,followers:[],following:[]};state.route='dashboard';persist();render();toast('Your profile is ready in this browser preview');break;}
  case 'onboard-back':auth.step=Math.max(1,auth.step-1);render();break;
  case 'onboard-next':{const d=auth.draft;if(auth.step===2&&!d.role){toast('Choose how you’d like to be part of Vericove');break;}if(auth.step===3){d.displayName=$('#display-name')?.value.trim()||d.name;d.handle=$('#username')?.value.trim().replace(/^@/,'')||d.name?.toLowerCase().replace(/[^a-z0-9]+/g,'').slice(0,20)||'member';d.bio=$('#profile-bio')?.value.trim()||'';d.specialty=$('[name="specialty"]')?.value.trim()||'';d.institution=$('[name="institution"]')?.value.trim()||'';}if(auth.step===4)d.anonymous=$('#anonymous-posting')?.checked??true;auth.step=Math.min(5,auth.step+1);render();break;}
  case 'profile-preview':{const p=user(),privacy=p.privacy||{},visible=key=>privacy[key]==='Public',display=visible('display')?(p.displayName||p.name):'Vericove member',avatar=visible('avatar')&&p.avatar?`<img class="public-preview-avatar" src="${esc(p.avatar)}" alt="Profile picture"/>`:'<span class="public-preview-avatar fallback">VC</span>',bio=visible('bio')&&p.bio?`<p>${esc(p.bio)}</p>`:'',interests=visible('interests')?(p.interests||[]).map(item=>`<span>${esc(item)}</span>`).join(''):'';modal('Public profile preview',`<div class="public-profile-preview"><div class="public-preview-cover banner-${esc(p.banner||'warm')}" ${p.bannerImage?`style="background-image:url('${esc(p.bannerImage)}')"`:''}></div>${avatar}<h3>${esc(display)}</h3><small>@${esc(p.handle||'member')}</small>${bio}<div class="final-interests">${interests||'<span>Interests are private</span>'}</div><div class="preview-privacy">${svg('eye',14)} Preview of information set to Public. Followers-only details remain hidden from visitors.</div></div>`,'','profile-sheet');break;}
  case 'view-member':{const name=button.dataset.name,handle=name.replace(/[^a-z0-9]+/gi,'').slice(0,24)||'member',self=handle===user().handle||name===user().name||name===user().displayName;const followed=(state.profileFollows||[]).some(item=>item.from===user().handle&&item.to===handle);if(self){go('profile');break;}modal(name,`<div class="member-preview"><span class="avatar">${esc(name.slice(0,2).toUpperCase())}</span><p class="username">@${esc(handle)}</p><p>Community member · sample profile based on a community post</p><span class="status-tag preprint">Pseudonymous</span><div class="modal-actions"><button class="btn" data-action="dm-coming">${svg('chat',14)} Message · Coming soon</button><button class="btn primary" data-action="toggle-member-follow" data-name="${esc(name)}" data-handle="${esc(handle)}">${followed?'Following':'Follow'}</button></div><small class="form-hint">Profile details and follow counts use local sample data in this prototype.</small></div>`,'','profile-sheet');break;}
  case 'toggle-member-follow':{const handle=button.dataset.handle,name=button.dataset.name;state.profileFollows||=[];const index=state.profileFollows.findIndex(item=>item.from===user().handle&&item.to===handle);if(index>=0){state.profileFollows.splice(index,1);state.session.following=(state.session.following||[]).filter(item=>item!==name);toast(`Unfollowed ${name}`);}else if(handle!==user().handle){state.profileFollows.push({from:user().handle,to:handle});state.session.following=[...new Set([...(state.session.following||[]),handle])];toast(`Following ${name}`);}persist();dismissModal();render();break;}
  case 'dm-coming':modal('Private messages are coming soon',`<div class="dm-coming"><span>${svg('chat',22)}</span><p>Private messaging is planned for a future Vericove release. No messages will be sent.</p></div>`);break;
  case 'profile-menu':modal('Profile options',`<div class="record-list"><button class="topic" data-route="settings"><span class="topic-emoji">${svg('shield',14)}</span><span><strong>Privacy & visibility</strong><small>Choose which profile details others can see</small></span><span class="topic-arrow">›</span></button><button class="topic" data-action="report-profile"><span class="topic-emoji">${svg('flag',14)}</span><span><strong>Report profile</strong><small>Let us know about a concern</small></span><span class="topic-arrow">›</span></button></div>`);break;
  case 'report-profile':dismissModal();toast('Profile reports require a connected moderation service');break;
  case 'profile-count':{const list=button.dataset.list,session=user();if(list==='posts'){auth.mode='login';toast(`${state.posts.filter(post=>post.ownerHandle===session.handle).length} posts on this profile`);break;}const relations=state.profileFollows||[];const names=list==='followers'?relations.filter(item=>item.to===session.handle).map(item=>item.from):relations.filter(item=>item.from===session.handle).map(item=>item.to);modal(list==='followers'?'Followers':'Following',names.length?`<div class="record-list">${names.map(name=>`<div class="record"><span class="record-main"><strong class="record-title">${esc(name)}</strong></span>${list==='following'?`<button class="btn small" data-action="unfollow-member" data-name="${esc(name)}">Following</button>`:''}</div>`).join('')}</div>`:`<p class="modal-intro">${list==='followers'?'No one follows this profile yet.':'You are not following any profiles yet.'}</p>`);break;}
  case 'unfollow-member':{const name=button.dataset.name;state.session.following=(state.session.following||[]).filter(item=>item!==name);state.profileFollows=(state.profileFollows||[]).filter(item=>!(item.from===user().handle&&item.to===name));persist();dismissModal();render();toast(`Unfollowed ${name}`);break;}
  case 'demo-signin':{const role=$('#workspace-role')?.value||'patient',names={patient:'Alex Morgan',doctor:'Demo Doctor',researcher:'Demo Researcher',explorer:'Guest Explorer'};state.session={loggedIn:true,remembered:true,demo:true,name:names[role]||names.patient,email:'',role,handle:role==='patient'?'QuietRiver':names[role].replaceAll(' ','')};if(!state.route)state.route='dashboard';persist();render();toast(`${roleName(role)} workspace is ready and remembered on this device`);break;}
  case 'signout':state.session.loggedIn=false;state.session.remembered=false;state.route='dashboard';persist();auth.mode='landing';render();break;
  default:break;
}}

function rolePicker(){modal('Choose a workspace',`<p class="modal-intro">Switch the sample workspace to preview the different role-based experiences in the architecture.</p><div class="role-options">${[['patient','Patient','Symptom intelligence and care navigation'],['doctor','Doctor','Professional workspace and verification'],['researcher','Researcher','Publications and collaboration'],['explorer','Public explorer','Public research and community']].map(([role,label,desc])=>`<button type="button" class="role-option ${user().role===role?'selected':''}" data-switch-role="${role}"><strong>${label}</strong><small>${desc}</small></button>`).join('')}</div><div class="research-sidebar-box"><strong>Demo role switching</strong>These role changes are local previews and do not create separate secured accounts.</div>`)}

document.addEventListener('click',event=>{
  const routeButton=event.target.closest('[data-route]');
  if(routeButton){event.preventDefault();const route=routeButton.dataset.route;if(!state.session?.loggedIn){state.route=route;persist();view('login');return;}go(route);return;}
  const viewButton=event.target.closest('[data-view]');
  if(viewButton){event.preventDefault();if(viewButton.dataset.view==='signup'){auth.step=1;auth.draft={role:'patient'};}view(viewButton.dataset.view);return;}
  const roleOption=event.target.closest('[data-role]');
  if(roleOption){auth.draft.role=roleOption.dataset.role;$$('.account-type').forEach(option=>{const selected=option.dataset.role===auth.draft.role;option.classList.toggle('selected',selected);const check=option.querySelector('i');if(check)check.textContent=selected?'✓':'';});return;}
  const avatarOption=event.target.closest('[data-avatar-option]');if(avatarOption){avatarDraft={src:avatarOption.dataset.avatarOption,kind:'preset',crop:{x:50,y:50,zoom:1}};$$('[data-avatar-option]').forEach(option=>option.classList.toggle('selected',option===avatarOption));updateAvatarTray();return;}
  const bannerOption=event.target.closest('[data-banner]');if(bannerOption){auth.draft.banner=bannerOption.dataset.banner;auth.draft.bannerImage='';$$('[data-banner]').forEach(option=>option.classList.toggle('selected',option===bannerOption));const mini=$('.mini-banner');if(mini){mini.className=`mini-banner banner-${auth.draft.banner}`;mini.style.backgroundImage='';}return;}
  const interestOption=event.target.closest('[data-interest]');if(interestOption){const interest=interestOption.dataset.interest;auth.draft.interests||=[];auth.draft.interests=auth.draft.interests.includes(interest)?auth.draft.interests.filter(item=>item!==interest):[...auth.draft.interests,interest];interestOption.classList.toggle('selected',auth.draft.interests.includes(interest));return;}
  const roleSwitch=event.target.closest('[data-switch-role]');
  if(roleSwitch){state.session.role=roleSwitch.dataset.switchRole;state.session.name=({patient:'Alex Morgan',doctor:'Demo Doctor',researcher:'Demo Researcher',explorer:'Guest Explorer'}[state.session.role]);state.session.handle=state.session.role==='patient'?'QuietRiver':state.session.name.replaceAll(' ','');state.route='dashboard';persist();render();toast(`${roleName(state.session.role)} workspace preview`);return;}
  const profileTab=event.target.closest('[data-profile-tab]');if(profileTab){state.profileTab=profileTab.dataset.profileTab;persist();render();return;}
  const actionButton=event.target.closest('[data-action]');
  if(actionButton){event.preventDefault();onAction(actionButton);return;}
  const communitySort=event.target.closest('[data-community-sort]');
  if(communitySort){$$('[data-community-sort]').forEach(button=>button.classList.toggle('active',button===communitySort));const list=$('#discussion-list');if(list){let posts=[...state.posts];if(communitySort.dataset.communitySort==='Helpful')posts.sort((a,b)=>b.votes-a.votes);if(communitySort.dataset.communitySort==='Recent')posts.sort((a,b)=>String(a.id).localeCompare(String(b.id)));if(communitySort.dataset.communitySort==='Following')posts=posts.filter(post=>state.followed.includes(post.community));list.innerHTML=posts.map(postCard).join('')||emptyState('Nothing here yet','Follow a community or start a conversation.');}return;}
  const communityView=event.target.closest('[data-community-view]');
  if(communityView){renderCommunityFeed(communityView.dataset.communityView);return;}
  const researchTab=event.target.closest('[data-research-tab]');
  if(researchTab){$$('[data-research-tab]').forEach(button=>button.classList.toggle('active',button===researchTab));const topic=researchTab.dataset.researchTab;const set=topic==='All research'?papers():topic==='My saved'?papers().filter(paper=>state.savedPapers.includes(paper.id)):papers().filter(paper=>paper.topic===topic);const list=$('#paper-list');if(list)list.innerHTML=set.map(paperCard).join('')||emptyState(topic==='My saved'?'No saved items yet':'No sample items in this topic','Save an item or try another research topic.');return;}
  const careFilter=event.target.closest('[data-care-filter]');
  if(careFilter){$$('[data-care-filter]').forEach(button=>button.classList.toggle('active',button===careFilter));const filter=careFilter.dataset.careFilter.toLowerCase();$$('[data-doctor]').forEach(card=>card.hidden=filter!=='all providers'&&!card.dataset.doctor.includes(filter));return;}
  const journalFilter=event.target.closest('[data-filter]');
  if(journalFilter){$$('[data-filter]').forEach(button=>button.classList.toggle('active',button===journalFilter));const key=journalFilter.dataset.filter;const entries=key==='Notes'?state.entries.filter(entry=>entry.note):key==='Medication'?[]:state.entries;const list=$('.entry-list');if(list)list.innerHTML=entries.map(entry=>`<article class="entry"><span class="entry-icon">${svg('pulse',15)}</span><div class="entry-main"><div class="entry-title">${esc(entry.symptom)}</div><div class="entry-meta">${fmtDate(entry.date)}${entry.time?` · ${esc(entry.time)}`:''} · ${esc(entry.duration||'Duration not recorded')}</div>${entry.note?`<div class="entry-note">${esc(entry.note)}</div>`:''}</div><div class="entry-side"><span class="severity ${entry.severity.toLowerCase()}">${esc(entry.severity)}</span></div></article>`).join('')||emptyState(key==='Medication'?'No medication notes yet':'No notes in this view','Add a journal entry when you would like to capture something.');return;}
});

document.addEventListener('submit',event=>{
  const form=event.target;
  if(form.id==='auth-form'){
    event.preventDefault();const data=Object.fromEntries(new FormData(form));
    if(auth.mode==='signup'){auth.draft={...auth.draft,...data};auth.step=2;render();return;}
    if(auth.mode==='forgot'){toast('Password reset requires a connected account service.');return;}
    const email=String(data.email||'');const proposedName=email.split('@')[0].split(/[._-]/).map(s=>s?`${s[0].toUpperCase()}${s.slice(1)}`:'').join(' ')||'Alex Morgan';const allowedRoles=['patient','doctor','researcher','explorer'];const role=allowedRoles.includes(data.role)?data.role:'patient';state.session={loggedIn:true,remembered:true,demo:true,name:proposedName,email,role,handle:role==='patient'?'QuietRiver':proposedName.replaceAll(' ','')};if(!state.route)state.route='dashboard';persist();render();toast(`${roleName(role)} workspace remembered on this device`);return;
  }
  if(form.id==='symptom-form'){
    event.preventDefault();const data=Object.fromEntries(new FormData(form));state.entries.unshift({id:Date.now(),symptom:data.symptom,date:data.date||isoToday,time:new Intl.DateTimeFormat('en',{hour:'numeric',minute:'2-digit'}).format(new Date()),severity:data.severity,duration:data.duration||'Duration not noted',note:data.note||''});persist();dismissModal();render();toast('Added to this browser demo');return;
  }
  if(form.id==='post-form'){
    event.preventDefault();if(form.dataset.videoMode==='true'&&selectedMedia?.type!=='video'){toast('Choose a video before sharing');return;}const data=Object.fromEntries(new FormData(form));const anonymous=data.anonymous==='yes',postId=`p${Date.now()}`;state.posts.unshift({id:postId,ownerHandle:user().handle,author:anonymous?(user().handle||'Member'):user().displayName||user().name,anonymous,time:'just now',community:data.community,tag:data.tag,title:data.title,body:data.body,votes:0,comments:[],voted:false,saved:false});if(selectedMedia?.url){sessionMedia.set(postId,selectedMedia);selectedMedia=null;}persist();dismissModal();state.route='community';state.communityView=form.dataset.videoMode==='true'?'Videos':'FYP';render();toast(anonymous?'Shared under your pseudonym':'Shared with your profile name');return;
  }
  if(form.id==='edit-post-form'){event.preventDefault();const post=state.posts.find(item=>item.id===form.dataset.id),data=Object.fromEntries(new FormData(form));if(post){post.title=String(data.title).trim();post.body=String(data.body).trim();persist();dismissModal();render();toast('Your changes are saved on this device');}return;}
  if(form.id==='story-form'){event.preventDefault();if(!selectedStory){toast('Choose a photo or video first');return;}const caption=String(new FormData(form).get('caption')||'').trim(),id=`s${Date.now()}`,author=user().handle||'Member';state.stories||=[];state.stories.unshift({id,author,caption,initials:author.slice(0,2).toUpperCase(),createdAt:Date.now()});sessionMedia.set(`story:${id}`,selectedStory);selectedStory=null;persist();dismissModal();render();toast('Your story is shared in this browser preview');return;
  }
  if(form.matches('.comment-form')){
    event.preventDefault();const data=Object.fromEntries(new FormData(form)),post=state.posts.find(item=>item.id===form.dataset.postId),text=String(data.comment||'').trim();if(post&&text){post.comments.push({id:`c${Date.now()}`,parentId:data.parentId||'',author:user().handle||'Member',text});persist();render();openComments(post);}return;
  }
  if(form.id==='report-form'){event.preventDefault();const data=Object.fromEntries(new FormData(form));state.reports.unshift({id:form.dataset.post,reason:data.reason,details:data.details||'',createdAt:Date.now()});persist();dismissModal();toast('Report saved to this browser’s moderation preview');return;}
  if(form.id==='review-form'){event.preventDefault();state.reviews.push(Object.fromEntries(new FormData(form)));persist();dismissModal();toast('Review preview saved on this device');return;}
  if(form.id==='profile-form'){event.preventDefault();const data=Object.fromEntries(new FormData(form));state.session.displayName=data.displayName;state.session.name=data.displayName;state.session.handle=data.handle.replace(/^@/,'');state.session.bio=data.bio||'';state.session.interests=String(data.interests||'').split(',').map(item=>item.trim()).filter(Boolean);if(user().role==='doctor')state.session.specialty=data.specialty||'';if(user().role==='researcher')state.session.institution=data.specialty||'';persist();dismissModal();render();toast('Profile saved on this device');return;}
  if(form.id==='enquiry-form'){event.preventDefault();const data=Object.fromEntries(new FormData(form));state.enquiries.unshift({message:data.message,date:isoToday});persist();dismissModal();toast('Enquiry draft saved on this device; nothing was sent');return;}
  if(form.id==='medication-form'){event.preventDefault();const data=Object.fromEntries(new FormData(form));state.medications.unshift({id:Date.now(),name:data.name,notes:data.notes||'',date:isoToday});persist();dismissModal();render();toast('Treatment note saved on this device');return;}
  if(form.id==='upload-research-form'){event.preventDefault();const data=Object.fromEntries(new FormData(form));state.publications.unshift({id:Date.now(),title:data.title,source:data.source,status:data.status});persist();dismissModal();render();toast('Publication draft saved on this device');return;}
  if(form.id==='verification-form'){event.preventDefault();dismissModal();toast('No application was saved or sent; verification service is not connected');return;}
  if(form.id==='research-search'){event.preventDefault();const query=String(new FormData(form).get('q')||'').trim().toLowerCase();const set=papers().filter(p=>`${p.title} ${p.summary} ${p.topic} ${p.authors}`.toLowerCase().includes(query));const list=$('#paper-list');if(list)list.innerHTML=set.map(paperCard).join('')||emptyState('No matching publications','Try a different condition, symptom or research topic.');return;}
  if(form.id==='report-form')event.preventDefault();
});

document.addEventListener('change',event=>{
  if(event.target.matches('[data-privacy]')){auth.draft.privacy||={};auth.draft.privacy[event.target.dataset.privacy]=event.target.value;return;}
  if(event.target.matches('[data-profile-privacy]')){state.session.privacy||={};state.session.privacy[event.target.dataset.profilePrivacy]=event.target.value;persist();toast('Profile visibility saved on this device');return;}
  if(event.target.id==='avatar-upload'&&event.target.files?.length){const file=event.target.files[0];if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>3*1024*1024){toast('Choose a JPG, PNG or WebP image under 3 MB');event.target.value='';return;}const reader=new FileReader();reader.onload=()=>{auth.draft.avatar=String(reader.result);const gallery=$('.avatar-gallery');if(gallery){const choice=document.createElement('button');choice.type='button';choice.className='avatar-choice selected';choice.dataset.avatar=auth.draft.avatar;choice.setAttribute('aria-label','Your uploaded profile picture');choice.innerHTML=`<img src="${auth.draft.avatar}" alt="" />`;gallery.prepend(choice);$$('.avatar-choice').forEach(item=>item.classList.toggle('selected',item===choice));const preview=$('.profile-mini-preview img');if(preview)preview.src=auth.draft.avatar;}};reader.readAsDataURL(file);event.target.value='';return;}
  if(event.target.id==='banner-upload'&&event.target.files?.length){const file=event.target.files[0];if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>3*1024*1024){toast('Choose a JPG, PNG or WebP cover under 3 MB');event.target.value='';return;}const reader=new FileReader();reader.onload=()=>{auth.draft.banner='custom';auth.draft.bannerImage=String(reader.result);$$('[data-banner]').forEach(item=>item.classList.toggle('selected',item.dataset.banner==='custom'));const preview=$('.mini-banner');if(preview){preview.className='mini-banner banner-custom';preview.style.backgroundImage=`url("${auth.draft.bannerImage}")`;}};reader.readAsDataURL(file);event.target.value='';return;}
  if(event.target.id==='profile-banner-upload'&&event.target.files?.length){const file=event.target.files[0];if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>3*1024*1024){toast('Choose a JPG, PNG or WebP cover under 3 MB');event.target.value='';return;}const reader=new FileReader();reader.onload=()=>{state.session.banner='custom';state.session.bannerImage=String(reader.result);persist();render();toast('Profile cover saved on this device');};reader.readAsDataURL(file);event.target.value='';return;}  if(event.target.id==='community-profile-avatar'&&event.target.files?.length){const file=event.target.files[0];if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>3*1024*1024){toast('Choose a JPG, PNG or WebP image under 3 MB');event.target.value='';return;}const reader=new FileReader();reader.onload=()=>{state.session.avatar=String(reader.result);persist();render();toast('Profile picture saved on this device');};reader.readAsDataURL(file);event.target.value='';return;}
});
document.addEventListener('change',event=>{if(event.target.id==='avatar-tray-file'&&event.target.files?.length){loadAvatarFile(event.target.files[0]);event.target.value='';}});
document.addEventListener('input',event=>{if(['avatar-x','avatar-y','avatar-zoom'].includes(event.target.id)&&avatarDraft){const key=event.target.id==='avatar-x'?'x':event.target.id==='avatar-y'?'y':'zoom';avatarDraft.crop[key]=Number(event.target.value);updateAvatarTray();}if(event.target.id==='profile-bio'){const count=$('#bio-count');if(count)count.textContent=String(event.target.value.length);const preview=$('.profile-mini-preview p');if(preview)preview.textContent=event.target.value||'Your bio will appear here.';}if(event.target.id==='display-name'){const preview=$('.profile-mini-preview>strong');if(preview)preview.textContent=event.target.value||'Your name';}if(event.target.id==='username'){const preview=$('.profile-mini-preview>small');if(preview)preview.textContent=`@${event.target.value||'yourname'}`;}});
document.addEventListener('dragover',event=>{if(event.target.closest('#avatar-dropzone')){event.preventDefault();$('#avatar-dropzone')?.classList.add('dragging');}});
document.addEventListener('dragleave',event=>{if(event.target.closest('#avatar-dropzone'))$('#avatar-dropzone')?.classList.remove('dragging');});
document.addEventListener('drop',event=>{if(event.target.closest('#avatar-dropzone')){event.preventDefault();$('#avatar-dropzone')?.classList.remove('dragging');loadAvatarFile(event.dataTransfer?.files?.[0]);}});

document.addEventListener('input',event=>{
  if(event.target.id==='doctor-search'){const query=event.target.value.toLowerCase();$$('[data-doctor]').forEach(card=>card.hidden=!card.dataset.doctor.includes(query));}
});
document.addEventListener('keydown',event=>{
  if(event.target.id==='global-search'&&event.key==='Enter'){const query=event.target.value.trim().toLowerCase();if(!query)return;const route=query.includes('doctor')||query.includes('care')?'care':query.includes('community')||query.includes('symptom')?'community':query.includes('research')||query.includes('study')?'research':'my-health';go(route);}
});

document.addEventListener('change',event=>{
  if(event.target.id==='post-photo'&&event.target.files?.length){
    const file=event.target.files[0];
    if((!file.type.startsWith('image/')&&!file.type.startsWith('video/'))||file.size>20*1024*1024){toast('Choose an image or video smaller than 20 MB');event.target.value='';return;}
    if(selectedMedia?.url)URL.revokeObjectURL(selectedMedia.url);
    selectedMedia={url:URL.createObjectURL(file),type:file.type.startsWith('video/')?'video':'image'};
    const preview=$('#media-preview');preview.innerHTML=selectedMedia.type==='video'?`<video src="${selectedMedia.url}" controls playsinline></video><button type="button" data-action="remove-photo">Remove video</button>`:`<img src="${selectedMedia.url}" alt="Selected photo preview" /><button type="button" data-action="remove-photo">Remove photo</button>`;preview.hidden=false;
    event.target.value='';return;
  }
  if(event.target.id==='story-media'&&event.target.files?.length){const file=event.target.files[0];if((!file.type.startsWith('image/')&&!file.type.startsWith('video/'))||file.size>20*1024*1024){toast('Choose a photo or video smaller than 20 MB');event.target.value='';return;}if(selectedStory?.url)URL.revokeObjectURL(selectedStory.url);selectedStory={url:URL.createObjectURL(file),type:file.type.startsWith('video/')?'video':'image'};const preview=$('#story-preview');preview.innerHTML=selectedStory.type==='video'?`<video src="${selectedStory.url}" controls playsinline></video>`:`<img src="${selectedStory.url}" alt="Story preview" />`;preview.hidden=false;event.target.value='';return;}
  if(event.target.id==='avatar-tray-file')return;
  if(event.target.type==='file'&&event.target.files?.length){const file=event.target.files[0];if(event.target.id==='record-file'){state.records.unshift({name:file.name.replace(/\.[^.]+$/,''),type:'Personal record',date:isoToday,file:file.name});persist();render();toast('Record added to this browser demo');}else toast('Upload is local-demo only.');event.target.value='';}
});
document.addEventListener('pointerdown',event=>{const button=event.target.closest('button');if(button)pressButton(button);});
document.addEventListener('pointerup',event=>{const button=event.target.closest('button');if(button)releaseButton(button);});
document.addEventListener('pointercancel',event=>{const button=event.target.closest('button');if(button)releaseButton(button);});
document.addEventListener('keydown',event=>{if(event.key==='Escape')dismissModal();});

